/*
 *  Name: "schema-import.js"
 *  Version: "0.2.0"
 *  Description: import schema generated by schema-sampler.js
 *  Disclaimer: https://raw.githubusercontent.com/tap1r/mongodb-scripts/master/DISCLAIMER.md
 *  Authors: ["tap1r <luke.prochazka@gmail.com>"]
 *  Roadmap: "https://raw.githubusercontent.com/tap1r/mongodb-scripts/master/ROADMAP.md" (required context)
 *
 *  Dual-shell snapshot: legacy/mongo-shell (v0.1.8). This file is mongosh-only.
 *
 *  Notes:
 *  - companion to schema-sampler.js. Reads JSON/EJSON of the sampler array
 *    [{ db, collections: [{ name, indexes, $sample }], views: [{ name, options }] }].
 *  - Do not Mongo.setReadPref(): mongosh reconnects. Writes already go primary.
 *  - createIndexes returns names and throws. insertMany insertedIds is an object;
 *    count keys, including a partial bulk error. Parenthesize (await write(...)).field.
 *  - --eval var options overlays optionDefaults. Do not declare options in this file.
 */

// Usage: mongosh [connection options] [--quiet] [--eval 'var options = {...};'] [-f|--file] </path/to/>schema-import.js
// Overlay: in-file optionDefaults then var options. Do not declare options in this file.
// schema.json must be JSON/EJSON of the schema-sampler array (not util.inspect).
//
//    mongosh --quiet --eval 'var options = { "schemaFile": "/path/to/schema.json" };' -f schema-import.js
//    mongosh --quiet --eval 'var options = { "schemaFile": "schema.json", "drop": true };' -f schema-import.js

/*
 *  In-file defaults. --eval var options overlays these.
 */

const optionDefaults = {
   "schemaFile": "schema.json",
   "drop": false
};

(async() => {
   const __script = { "name": "schema-import.js", "version": "0.2.0" };
   console.log(`\n\x1b[33m#### Running script ${__script.name} v${__script.version} on shell v${version()}\x1b[0m`);

   const SKIP_INDEX_FIELDS = new Set(['v', 'ns', 'background']);

   function isPlainObject(value) {
      return !!value && typeof value === 'object' && !Array.isArray(value);
   }

   function hasOwn(obj, key) {
      return !!obj && Object.prototype.hasOwnProperty.call(obj, key);
   }

   function errText(e) {
      return (e && (e.errmsg || e.message)) || String(e);
   }

   function plural(n, one, many) {
      return n === 1 ? one : many;
   }

   function insertedCount(errOrResult) {
      if (!errOrResult) return 0;
      const ids = errOrResult.insertedIds
         || (errOrResult.result && errOrResult.result.insertedIds);
      if (!ids || typeof ids !== 'object') return 0;
      return Object.keys(ids).length;
   }

   function indexSpec(idx) {
      if (!isPlainObject(idx) || !isPlainObject(idx.key)) return null;
      if (idx.name === '_id_') return null;
      const spec = {};
      Object.keys(idx).forEach(key => {
         if (!SKIP_INDEX_FIELDS.has(key))
            spec[key] = idx[key];
      });
      return spec;
   }

   // Caller: var options = { ... } (--eval or REPL). Do not declare or assign it in this file.
   const overlay = (typeof options !== 'undefined' && options) ? options : null;
   const resolved = {
      "schemaFile": (overlay && overlay.schemaFile != null)
         ? overlay.schemaFile
         : optionDefaults.schemaFile,
      "drop": (overlay && hasOwn(overlay, 'drop')) ? !!overlay.drop : optionDefaults.drop
   };

   function loadSchemaFile(file) {
      if (typeof file !== 'string' || file.length === 0)
         throw new Error(`${__script.name}: schemaFile is empty`);
      let text;
      try {
         text = fs.readFileSync(file, 'utf8');
      } catch(e) {
         throw new Error(`${__script.name}: cannot read "${file}": ${errText(e)}`);
      }
      try {
         if (typeof EJSON !== 'undefined' && typeof EJSON.parse === 'function')
            return EJSON.parse(text);
         return JSON.parse(text);
      } catch(e) {
         throw new Error(`${__script.name}: "${file}" is not JSON/EJSON of the schema-sampler array`);
      }
   }

   function listDBs(schema) {
      if (!Array.isArray(schema))
         throw new Error(`${__script.name}: schema must be an array of { db, collections, views }`);
      return schema
         .map(entry => entry && entry.db)
         .filter(name => typeof name === 'string' && name.length > 0);
   }

   function collectionExists(database, name) {
      return database.getCollectionNames().includes(name);
   }

   async function insertSample(namespace, docs, ns) {
      if (!Array.isArray(docs) || docs.length === 0) return 0;
      try {
         return insertedCount((await namespace.insertMany(docs, { "ordered": false })));
      } catch(e) {
         const n = insertedCount(e) || insertedCount(e.result);
         console.log(`\x1b[33m[WARN]\x1b[0m insertMany ${ns}: ${n} ${plural(n, 'document', 'documents')} inserted (${errText(e)})`);
         return n;
      }
   }

   async function createIndexSet(namespace, indexes, ns) {
      const specs = (Array.isArray(indexes) ? indexes : []).map(indexSpec).filter(Boolean);
      if (specs.length === 0) return;
      const names = (await namespace.createIndexes(specs));
      const list = Array.isArray(names) ? names.join(', ') : String(names);
      console.log(`indexes ${ns}: ${list}`);
   }

   async function importCollection(database, coll, drop) {
      const name = coll && coll.name;
      if (typeof name !== 'string' || name.length === 0) {
         console.log('\x1b[33m[WARN]\x1b[0m skip collection with no name');
         return;
      }
      const ns = `${database.getName()}.${name}`;
      if (collectionExists(database, name)) {
         if (!drop) {
            console.log(`\x1b[33m[WARN]\x1b[0m skip existing collection ${ns} (set drop: true to replace)`);
            return;
         }
         database.getCollection(name).drop();
      }
      database.createCollection(name);
      const namespace = database.getCollection(name);
      const n = await insertSample(namespace, coll.$sample, ns);
      console.log(`collection ${ns}: ${n} ${plural(n, 'document', 'documents')}`);
      await createIndexSet(namespace, coll.indexes, ns);
   }

   async function importView(database, view, drop) {
      const name = view && view.name;
      if (typeof name !== 'string' || name.length === 0) {
         console.log('\x1b[33m[WARN]\x1b[0m skip view with no name');
         return;
      }
      const opts = isPlainObject(view.options) ? view.options : {};
      const viewOn = opts.viewOn;
      const pipeline = opts.pipeline;
      const ns = `${database.getName()}.${name}`;
      if (typeof viewOn !== 'string' || !Array.isArray(pipeline)) {
         console.log(`\x1b[33m[WARN]\x1b[0m skip view ${ns}: sampler JSON has no viewOn/pipeline`);
         return;
      }
      if (collectionExists(database, name)) {
         if (!drop) {
            console.log(`\x1b[33m[WARN]\x1b[0m skip existing view ${ns} (set drop: true to replace)`);
            return;
         }
         database.getCollection(name).drop();
      }
      const extra = {};
      if (opts.collation) extra.collation = opts.collation;
      database.createView(name, viewOn, pipeline, extra);
      console.log(`view ${ns} on ${viewOn}`);
   }

   async function importDatabase(entry, drop) {
      const dbName = entry && entry.db;
      if (typeof dbName !== 'string' || dbName.length === 0) return;
      const database = db.getSiblingDB(dbName);
      const collections = Array.isArray(entry.collections) ? entry.collections : [];
      const views = Array.isArray(entry.views) ? entry.views : [];
      for (let i = 0; i < collections.length; i++)
         await importCollection(database, collections[i], drop);
      for (let i = 0; i < views.length; i++)
         await importView(database, views[i], drop);
   }

   async function main({ schemaFile = 'schema.json', drop = false } = {}) {
      // Do not Mongo.setReadPref(): mongosh reconnects. Writes already go primary.
      const schema = loadSchemaFile(schemaFile);
      const dbNames = listDBs(schema);
      console.log(`schema file "${schemaFile}"`);
      console.log(`databases: ${dbNames.join(', ') || '(none)'}`);
      if (drop)
         console.log('drop: true (existing collections/views named in the schema are replaced)');
      if (dbNames.length === 0) return;
      const failures = [];
      for (let i = 0; i < schema.length; i++) {
         try {
            await importDatabase(schema[i], drop);
         } catch(e) {
            failures.push(`${schema[i] && schema[i].db ? schema[i].db : i}: ${errText(e)}`);
         }
      }
      if (failures.length > 0) {
         throw new Error(`${__script.name}: ${failures.length} ${plural(failures.length, 'database', 'databases')} failed\n${failures.join('\n')}`);
      }
   }

   await main(resolved);
})();

// EOF
